print("unique:", len(set(texts)))
for q in all_q:
    assert len(q["o"]) == 4, q["q"]
    assert 0 <= q["a"] <= 3, q["q"]
    assert len(set(q["o"])) == 4, ("duplicate option text!", q["q"])
multi = sum(1 for q in all_q if "\n" in q["q"] or "List-" in q["q"] or "Assertion" in q["q"])
print("multi-format %:", round(100*multi/len(all_q), 1))

chapter = {
    "id": "arctic_or_polar_climate",
    "title": "The Arctic or Polar Climate",
    "desc": "Regional climatology (from Goh Cheng Leong's Physical Geography, Ch.25, and NCERT XI Fundamentals of Physical Geography, Ch.12 'World Climate and Climate Change'): distribution of ice-cap and tundra regions; extreme temperature and permafrost; light, cyclone-dependent precipitation patterns; tundra vegetation (mosses, lichens, reindeer moss) and its tree-line limit; indigenous Arctic peoples (Eskimos, Lapps, Samoyeds, Yakuts) and their adaptations; recent mineral/shipping development of the Arctic; merged with NCERT's Koeppen classification and the corresponding Polar Climates (ET Tundra, EF Ice Cap) types — concluding the world climate-types sequence begun in Ch.15",
    "questions": data
}

